import unittest

from solucao import comeca_com
from solucao import termina_com


class TestComecaETermina(unittest.TestCase):
    def test_comeca_com_true(self):
        """comeca_com devolve True quando o texto comeca com o pedaco"""
        self.assertEqual(comeca_com("banana", "ban"), True)

    def test_comeca_com_false_mesmo_dentro(self):
        """comeca_com devolve False quando o pedaco esta so no meio"""
        self.assertEqual(comeca_com("banana", "ana"), False)

    def test_termina_com_true(self):
        """termina_com devolve True quando o texto termina com o pedaco"""
        self.assertEqual(termina_com("banana", "ana"), True)

    def test_termina_com_false_mesmo_no_comeco(self):
        """termina_com devolve False quando o pedaco esta so no comeco"""
        self.assertEqual(termina_com("banana", "ban"), False)

